<?php use App\Core\CSRF;$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<div class="sports-head"><div><span class="sports-kicker">TORNEIO</span><h1><?=$e($tournament['name'])?></h1><p><?=$e($tournament['modality_name']??'')?> · <?=$e($tournament['category']??'')?> · <?=$e($tournament['format'])?></p></div><a class="btn btn-outline-secondary" href="/sports/tournaments">Todos os torneios</a></div>
<?php if($tournament['champion_name']):?><div class="alert alert-success"><strong>🏆 Campeão: <?=$e($tournament['champion_name'])?></strong></div><?php endif;?>
<div class="row g-4"><div class="col-lg-4"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Cadastrar equipe</h2><form method="post" action="/sports/tournaments/<?=(int)$tournament['id']?>/teams"><?=CSRF::field()?><input class="form-control mb-2" name="name" placeholder="Nome da equipe" required><select class="form-select mb-2" name="captain_customer_id"><option value="">Capitão opcional</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=$e($c['name'])?></option><?php endforeach;?></select><button class="btn btn-primary w-100">Adicionar equipe</button></form></div></div>
<?php if($teams):?><form method="post" action="/sports/tournaments/<?=(int)$tournament['id']?>/fixtures" class="mt-3" onsubmit="return confirm('Gerar tabela de jogos com as equipes atuais?')"><?=CSRF::field()?><button class="btn btn-success w-100" <?=!empty($matches)?'disabled':''?>>Gerar tabela / chaveamento</button></form><?php endif;?></div>
<div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Equipes e jogadores</h2><?php foreach($teams as $team):?><div class="border rounded-3 p-3 mb-2"><div class="d-flex justify-content-between"><strong><?=$e($team['name'])?></strong><span><?=$e($team['group_name']??'')?> · <?=(int)$team['players']?> jogador(es)</span></div><?php if(!empty($playersByTeam[(int)$team['id']])):?><small><?=implode(', ',array_map(fn($p)=>$e($p['name']).($p['jersey_number']?' #'.(int)$p['jersey_number']:''),$playersByTeam[(int)$team['id']]))?></small><?php endif;?><form class="row g-1 mt-2" method="post" action="/sports/tournaments/<?=(int)$tournament['id']?>/teams/<?=(int)$team['id']?>/players"><?=CSRF::field()?><div class="col-8"><select class="form-select form-select-sm" name="customer_id" required><option value="">Adicionar jogador</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=$e($c['name'])?></option><?php endforeach;?></select></div><div class="col-2"><input class="form-control form-control-sm" type="number" name="jersey_number" placeholder="#"></div><div class="col-2"><button class="btn btn-sm btn-outline-primary w-100">+</button></div></form></div><?php endforeach;?></div></div></div></div>
<?php if($standings):?><div class="card border-0 shadow-sm mt-4"><div class="card-body"><h2 class="h5">Classificação</h2><div class="table-responsive"><table class="table"><thead><tr><th>Grupo</th><th>Equipe</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th><th>Pts</th></tr></thead><tbody><?php foreach($standings as $r):?><tr><td><?=$e($r['group_name'])?></td><td><strong><?=$e($r['name'])?></strong></td><td><?=$r['played']?></td><td><?=$r['wins']?></td><td><?=$r['draws']?></td><td><?=$r['losses']?></td><td><?=$r['gf']?></td><td><?=$r['ga']?></td><td><?=$r['gd']?></td><td><strong><?=$r['points']?></strong></td></tr><?php endforeach;?></tbody></table></div></div></div><?php endif;?>
<?php if($matches):?><div class="card border-0 shadow-sm mt-4"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">Partidas</h2><form method="post" action="/sports/tournaments/<?=(int)$tournament['id']?>/advance"><?=CSRF::field()?><button class="btn btn-sm btn-outline-success">Avançar fase / concluir</button></form></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Fase</th><th>Partida</th><th>Agenda</th><th>Placar</th></tr></thead><tbody><?php foreach($matches as $m):?><tr><td><?=$e(($m['group_name']?:$m['phase']).($m['round_number']?' · R'.$m['round_number']:''))?></td><td><strong><?=$e($m['home_name']??'A definir')?> × <?=$e($m['away_name']??'BYE')?></strong></td><td><?php if($m['starts_at']):?><?=$e($m['court_name'])?> · <?=date('d/m H:i',strtotime($m['starts_at']))?><?php elseif($m['away_team_id']):?><form class="d-flex gap-1" method="post" action="/sports/tournaments/<?=(int)$tournament['id']?>/matches/<?=(int)$m['id']?>/schedule"><?=CSRF::field()?><select class="form-select form-select-sm" name="court_id"><?php foreach($courts as $c):?><option value="<?=(int)$c['id']?>"><?=$e($c['name'])?></option><?php endforeach;?></select><input class="form-control form-control-sm" type="datetime-local" name="starts_at" required><input type="hidden" name="duration_minutes" value="60"><button class="btn btn-sm btn-outline-primary">Agendar</button></form><?php endif;?></td><td><?php if($m['away_team_id']):?><form class="d-flex gap-1" method="post" action="/sports/tournaments/<?=(int)$tournament['id']?>/matches/<?=(int)$m['id']?>/score"><?=CSRF::field()?><input class="form-control form-control-sm" style="width:70px" type="number" min="0" name="home_score" value="<?=$m['home_score']!==null?(int)$m['home_score']:''?>"><span>×</span><input class="form-control form-control-sm" style="width:70px" type="number" min="0" name="away_score" value="<?=$m['away_score']!==null?(int)$m['away_score']:''?>"><button class="btn btn-sm btn-success">Salvar</button></form><?php else:?>Classificada por bye<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php endif;?>
